  const c1 = { type: 'BillingAdjust', payload: { orderId: evt.data.orderId, delta: evt.data.promoDelta }, correlationId: evt.correlationId };
  const c2 = { type: 'InventoryAdjust', payload: { productId: evt.data.productId, delta: evt.data.promoUnitsDelta }, correlationId: evt.correlationId };
